#!/usr/bin/env bash
# ZONO — apply אנשים (server-paginated relationship command center).
# Realigns to origin/main, applies the commit, pushes. macOS-safe base64 decode.
set -euo pipefail
cd "$(dirname "$0")"
echo "→ repo: $(pwd)"
git am --abort 2>/dev/null || true
git fetch origin
git checkout main
git reset --hard origin/main
cat > /tmp/zono-people.patch.b64 <<'B64EOF'

B64EOF
base64 -d < /tmp/zono-people.patch.b64 > /tmp/zono-people.patch
git am /tmp/zono-people.patch
echo "→ commit applied:"; git log --oneline -2
git push origin main
echo "✓ pushed. Redeploy will pick up /people."
